Here is a Template Method-based implementation in Python that defines a SortAlgorithm template with abstract compare and swap methods, and concrete BubbleSort and SelectionSort variants. It uses a mode-driven skeleton in the base class so both algorithms share the same overall structure while differing in how elements are compared and swapped.

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    """
    Template Method: sort(data) defines the skeleton of the sorting algorithm.
    It delegates element comparison to compare(a, b) and swapping to swap(data, i, j).
    Subclasses configure the concrete algorithm by setting the _mode and
    implementing the two abstract operations.
    """
    @abstractmethod
    def compare(self, a: Any, b: Any) -> int:
        """
        Return negative if a < b, zero if a == b, positive if a > b.
        """
        pass

    @abstractmethod
    def swap(self, data: List[Any], i: int, j: int) -> None:
        """Swap elements at indices i and j in data."""
        pass

    def sort(self, data: List[Any]) -> None:
        n = len(data)
        mode = getattr(self, "_mode", None)

        if mode == "bubble":
            # Bubble sort skeleton using compare/swap
            for i in range(n):
                for j in range(0, n - 1 - i):
                    if self.compare(data[j], data[j + 1]) > 0:
                        self.swap(data, j, j + 1)
        elif mode == "selection":
            # Selection sort skeleton using compare/swap
            for i in range(n):
                min_idx = i
                for j in range(i + 1, n):
                    if self.compare(data[min_idx], data[j]) > 0:
                        min_idx = j
                if min_idx != i:
                    self.swap(data, i, min_idx)
        else:
            raise ValueError("SortAlgorithm: unsupported mode configured")

class BubbleSort(SortAlgorithm):
    def __init__(self):
        self._mode = "bubble"

    def compare(self, a: Any, b: Any) -> int:
        return (a > b) - (a < b)

    def swap(self, data: List[Any], i: int, j: int) -> None:
        data[i], data[j] = data[j], data[i]

class SelectionSort(SortAlgorithm):
    def __init__(self):
        self._mode = "selection"

    def compare(self, a: Any, b: Any) -> int:
        return (a > b) - (a < b)

    def swap(self, data: List[Any], i: int, j: int) -> None:
        data[i], data[j] = data[j], data[i]

# Testing the implementation
def main():
    arrays = [
        [3, 1, 4, 2, 5],
        ["delta", "alpha", "charlie", "bravo"]
    ]

    bubble_sort = BubbleSort()
    selection_sort = SelectionSort()

    for arr in arrays:
        a = list(arr)  # copy for BubbleSort
        b = list(arr)  # copy for SelectionSort

        bubble_sort.sort(a)
        selection_sort.sort(b)

        print(f"Original: {arr}")
        print(f"BubbleSort: {a}")
        print(f"SelectionSort: {b}")
        print()

if __name__ == "__main__":
    main()
